    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Simultaneous operator approximation", H("Simultaneous operator approximation"), Blocks(
        Paragraph(Text("Every operator x in the bicommutant of a unital star subalgebra S can be approximated on any finite family of vectors: for every positive epsilon, some s in S has norm(x(v)-s(v)) less than epsilon on each vector. The one-vector case uses the projection onto the closed orbit subspace. Finite diagonal amplification yields simultaneous approximation.")),
        Describe.Lean(DescribeId.Create("statement0"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/VonNeumannAlgebra/Density.piLpEntry_apply"),
            H("piLpEntry_apply"), StatementSource.FromAuthor(Disp(Statement0())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The definition piLpEntry composes the single-coordinate inclusion, T, and the coordinate projection. Evaluating this composition gives the i-th coordinate of T applied to the vector supported at j; piLpEntry_apply is consequently definitional."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement1"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/VonNeumannAlgebra/Density.apply_eq_sum_piLpEntry"),
            H("apply_eq_sum_piLpEntry"), StatementSource.FromAuthor(Disp(Statement1())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Decompose w into the finite sum of its single-coordinate vectors. Continuous linearity moves T through this sum, and piLpEntry_apply identifies each resulting i-th component with the corresponding matrix entry applied to w(j)."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement2"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/VonNeumannAlgebra/Density.diagStarAlgHom_apply"),
            H("diagStarAlgHom_apply"), StatementSource.FromAuthor(Disp(Statement2())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("diagStarAlgHom conjugates the coordinatewise operator by PiLp.continuousLinearEquiv. Evaluating at coordinate i cancels the change of presentation and leaves s applied to w(i), so the formula follows directly from the definition."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement3"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/VonNeumannAlgebra/Density.diagStarAlgHom_apply_single"),
            H("diagStarAlgHom_apply_single"), StatementSource.FromAuthor(Disp(Statement3())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Use diagStarAlgHom_apply coordinatewise. At coordinate j the single vector evaluates to h, giving s(h); at every other coordinate it evaluates to zero and s maps zero to zero. Extensionality identifies the resulting vector with the single vector at j."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement4"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/VonNeumannAlgebra/Density.isReducing_iff"),
            H("isReducing_iff"), StatementSource.FromAuthor(Disp(Statement4())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("IsReducing is defined as invariance of U together with invariance of its orthogonal complement. Unfolding that definition gives the equivalence; it introduces no completeness or existence-of-projection assumption."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement5"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/VonNeumannAlgebra/Density.isReducing_coe_iff_commute_starProjection"),
            H("isReducing_coe_iff_commute_starProjection"), StatementSource.FromAuthor(Disp(Statement5())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Apply ContinuousLinearMap.IsIdempotentElem.commute_iff to the orthogonal projection, using isIdempotentElem_starProjection. Its range is U and its kernel is the orthogonal complement by range_starProjection and ker_starProjection, so the two invariant-subspace conditions become isReducing_iff."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement6"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/VonNeumannAlgebra/Density.isReducing_iff_mem_invtSubmodule_adjoint"),
            H("isReducing_iff_mem_invtSubmodule_adjoint"), StatementSource.FromAuthor(Disp(Statement6())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Expand isReducing_iff. The standard relation mem_invtSubmodule_adjoint_iff identifies invariance of the orthogonal complement under A with invariance of U under its adjoint. Rewriting gives the stated pair of invariance conditions under the given projection and completeness assumptions."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement7"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/VonNeumannAlgebra/Density.continuous_ofPointwiseConvergenceCLM"),
            H("continuous_ofPointwiseConvergenceCLM"), StatementSource.FromAuthor(Disp(Statement7())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Use continuous_of_dual_apply_continuous for the weak operator topology. Each test coefficient is a continuous functional y applied to evaluation at x; continuous_eval_const supplies pointwise continuity and composition with y.continuous gives the required continuity of every test."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement8"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/VonNeumannAlgebra/Density.isClosed_image_ofCLM_centralizer"),
            H("isClosed_image_ofCLM_centralizer"), StatementSource.FromAuthor(Disp(Statement8())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("ContinuousLinearMapWOT.ofCLM is bijective and preserves multiplication, so its image of a centralizer is the centralizer of the image. The identity follows by testing commutation elementwise with mem_centralizer_iff and ofCLM_injective. Then isClosed_centralizer gives weak operator closedness, using the separating-dual hypotheses of the operator space."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement9"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/VonNeumannAlgebra/Density.continuous_strongDual_apply_toPointwiseConvergenceCLM"),
            H("continuous_strongDual_apply_toPointwiseConvergenceCLM"), StatementSource.FromAuthor(Disp(Statement9())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("PointwiseConvergenceCLM.exists_finset_sum_eq expresses phi as a finite sum of coefficients g(x)(A x). Each coefficient is weak-operator continuous by continuous_dual_apply, and continuous_finsetSum preserves continuity. Thus no functional is lost on passing from the strong to the weak operator topology."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement10"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/VonNeumannAlgebra/Density.toPointwiseConvergenceCLM_mem_closure_image_iff"),
            H("toPointwiseConvergenceCLM_mem_closure_image_iff"), StatementSource.FromAuthor(Disp(Statement10())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The continuous identity continuous_ofPointwiseConvergenceCLM sends the strong closure into the weak closure. For the converse, use the linear identity e from the weak copy to the pointwise copy and the convex image of s. LinearMap.image_closure_of_convex applies because continuous_strongDual_apply_toPointwiseConvergenceCLM makes every pulled-back continuous linear functional continuous; it transfers weak closure membership to strong closure membership without asserting that e itself is continuous."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement11"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/VonNeumannAlgebra/Density.closure_image_toPointwiseConvergenceCLM"),
            H("closure_image_toPointwiseConvergenceCLM"), StatementSource.FromAuthor(Disp(Statement11())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The bicommutant is weak-operator closed by isClosed_image_ofCLM_centralizer, so its image is strongly closed by continuous_ofPointwiseConvergenceCLM and contains the strong closure of S. Conversely a basic strong neighborhood tests finitely many vectors; exists_forall_norm_sub_apply_lt_of_mem_centralizer_centralizer supplies an element of S satisfying all these tests. This proves both inclusions."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement12"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/VonNeumannAlgebra/Density.closure_image_ofCLM"),
            H("closure_image_ofCLM"), StatementSource.FromAuthor(Disp(Statement12())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Weak closedness of the bicommutant and Set.subset_centralizer_centralizer give one inclusion. For the reverse, closure_image_toPointwiseConvergenceCLM gives strong closure membership of each bicommutant element. The continuous identity continuous_ofPointwiseConvergenceCLM carries it to the weak closure."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement13"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/VonNeumannAlgebra/Density.closure_image_ofCLM_inter_selfAdjoint"),
            H("closure_image_ofCLM_inter_selfAdjoint"), StatementSource.FromAuthor(Disp(Statement13())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("A weak limit of self-adjoint elements lies in the bicommutant by closure_image_ofCLM and remains self-adjoint because the fixed set of continuous star is closed. Conversely apply the weak-operator continuous real-part map A mapped to one half times (A+star A) to weak approximation from S. It stays in S and is self-adjoint, and fixes a self-adjoint target."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement14"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/VonNeumannAlgebra/Density.closure_image_toPointwiseConvergenceCLM_inter_selfAdjoint"),
            H("closure_image_toPointwiseConvergenceCLM_inter_selfAdjoint"), StatementSource.FromAuthor(Disp(Statement14())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The self-adjoint part of S is convex over the real numbers: it is the intersection of the real submodule underlying S with selfAdjoint.submodule. Apply Convex.toPointwiseConvergenceCLM_mem_closure_image_iff to equate its strong and weak closure memberships. Then closure_image_ofCLM_inter_selfAdjoint and injectivity of the two topology-copy maps identify the common set with the self-adjoint bicommutant."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement15"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/VonNeumannAlgebra/Density.apply_mem_closure_of_mem_centralizer_centralizer"),
            H("apply_mem_closure_of_mem_centralizer_centralizer"), StatementSource.FromAuthor(Disp(Statement15())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Let K be the closed submodule generated by the orbit S v. Multiplication preserves that orbit and continuity preserves its closure, so K is invariant under S and its adjoints. The reducing-subspace projection criterion puts K.starProjection in the commutant; since x is in the bicommutant, it commutes with this projection. The unit puts v in K, hence the projection fixes x v as well, proving that x v is in the orbit closure."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement16"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/VonNeumannAlgebra/Density.exists_forall_norm_sub_apply_lt_of_mem_centralizer_centralizer"),
            H("exists_forall_norm_sub_apply_lt_of_mem_centralizer_centralizer"), StatementSource.FromAuthor(Disp(Statement16())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Pass to the finite Hilbert sum indexed by the given finite family. The helper diag_mem_centralizer_centralizer proves that the diagonal amplification of x is in the amplified bicommutant: matrix entries of a commuting operator lie in S', and x commutes with each entry. Apply apply_mem_closure_of_mem_centralizer_centralizer to the single vector of all v(i); Metric.mem_closure_iff gives an approximant, and PiLp.norm_apply_le bounds each coordinate error by its total Hilbert-sum error."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement17"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/VonNeumannAlgebra/Density.toPointwiseConvergenceCLM_injective"),
            H("toPointwiseConvergenceCLM_injective"), StatementSource.FromAuthor(Disp(Statement17())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Equality after toPointwiseConvergenceCLM implies equality of the evaluations at every v by congrArg. ContinuousLinearMap.ext then identifies the original maps, so changing the topology copy identifies no distinct operators."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("pointwisestatement0"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/VonNeumannAlgebra/Density.exists_finset_sum_eq"),
            H("exists_finset_sum_eq"), StatementSource.FromAuthor(Disp(PointwiseStatement0())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Seminorm.bound_of_continuous bounds phi by finitely many evaluations, so phi factors through the finite-coordinate linear map Phi:T mapped to (T x) on a finite set s. The norm bound makes this factor well defined on range(Phi). Module.Dual.exists_continuous_extension_of_le_seminorm extends it to all of the finite product; decomposing that extension by ContinuousLinearMap.sum_comp_single yields one continuous functional on F per coordinate and the required finite sum."))), DescribeRole.Theorem))));

